# Surah Al-Ma'ida (chapter 5) — part 5: ayat 41-50 (IDs 710-719)
SURAH = 5

ENTRIES = {
710: (
"اے رسول! وہ لوگ جو کفر کی طرف تیزی سے پیش قدمی کرتے ہیں آپ کو غمگین نہ کریں — وہ لوگ جنہوں نے اپنے منہ سے تو کہا: ہم ایمان لائے — حالانکہ ان کے دل ایمان نہیں لائے — اور وہ لوگ جو یہود ہیں — جھوٹی بات سننے والے — دوسرے لوگوں (کی نمائندگی کرنے والے) سننے والے — جو آپ تک نہیں پہنچے — وہ کلمات کو — ان کے مقامات کے بعد — بدل دیتے ہیں — وہ کہتے ہیں: اگر تمہیں یہ — (فتویٰ) مل جائے — تو اسے لے لو — اور اگر یہ نہ ملے تو ہوشیار رہو — اور جسے اللہ آزمائش میں ڈالنا چاہے — تو آپ اللہ کے مقابلے میں اس کے حق میں کچھ نہیں کر سکتے — یہی وہ لوگ ہیں جن کے دلوں کو پاک کرنے کا اللہ نے ارادہ نہیں کیا — ان کے لیے دنیا میں رسوائی ہے اور آخرت میں بہت بڑا عذاب ہے",
"""۱۔ منافق اور یہود — نبی ﷺ کے لیے غمگین کرنے والے۔
۲۔ ’’يَا أَيُّهَا الرَّسُولُ لَا يَحْزُنكَ الَّذِينَ يُسَارِعُونَ فِي الْكُفْرِ‘‘ — اے رسول! وہ لوگ جو کفر کی طرف تیزی سے پیش قدمی کرتے ہیں آپ کو غمگین نہ کریں — یعنی کفار کی تیزی دیکھ کر آپ غمگین نہ ہوں۔
۳۔ ’’مِنَ الَّذِينَ قَالُوا آمَنَّا بِأَفْوَاهِهِمْ وَلَمْ تُؤْمِن قُلُوبُهُمْ‘‘ — وہ لوگ جنہوں نے اپنے منہ سے تو کہا: ہم ایمان لائے — حالانکہ ان کے دل ایمان نہیں لائے — یعنی منافق۔
۴۔ ’’وَمِنَ الَّذِينَ هَادُوا سَمَّاعُونَ لِلْكَذِبِ سَمَّاعُونَ لِقَوْمٍ آخَرِينَ لَمْ يَأْتُوكَ‘‘ — اور وہ لوگ جو یہود ہیں — جھوٹی بات سننے والے — دوسرے لوگوں (کی نمائندگی کرنے والے) سننے والے — جو آپ تک نہیں پہنچے — یعنی یہود کے سردار نبی ﷺ کے پاس نہیں آتے لیکن سننے والے جاسوسی کرتے تھے۔
۵۔ ’’يُحَرِّفُونَ الْكَلِمَ مِن بَعْدِ مَوَاضِعِهِ يَقُولُونَ إِنْ أُوتِيتُمْ هَٰذَا فَخُذُوهُ وَإِن لَّمْ تُؤْتَوْهُ فَاحْذَرُوا‘‘ — وہ کلمات کو — ان کے مقامات کے بعد — بدل دیتے ہیں — وہ کہتے ہیں: اگر تمہیں یہ — (فتویٰ) مل جائے — تو اسے لے لو — اور اگر یہ نہ ملے تو ہوشیار رہو — یعنی اپنے مفاد کے مطابق فتویٰ لینے کا منصوبہ۔
۶۔ ’’وَمَن يُرِدِ اللّٰہُ فِتْنَتَهُ فَلَن تَمْلِكَ لَهُ مِنَ اللّٰہِ شَيْئًا‘‘ — اور جسے اللہ آزمائش میں ڈالنا چاہے — تو آپ اللہ کے مقابلے میں اس کے حق میں کچھ نہیں کر سکتے۔
۷۔ ’’أُولَٰئِكَ الَّذِينَ لَمْ يُرِدِ اللّٰہُ أَن يُطَهِّرَ قُلُوبَهُمْ لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَۃِ عَذَابٌ عَظِيمٌ‘‘ — یہی وہ لوگ ہیں جن کے دلوں کو پاک کرنے کا اللہ نے ارادہ نہیں کیا — ان کے لیے دنیا میں رسوائی ہے اور آخرت میں بہت بڑا عذاب ہے۔
۸۔ عملی سبق: دشمن کی چالاکیوں سے غمگین نہ ہو؛ اللہ پر بھروسہ رکھو۔"""
),
711: (
"وہ جھوٹی بات سننے والے ہیں — حرام (مال) کھانے والے ہیں — پس اگر وہ آپ کے پاس آئیں تو آپ ان کے درمیان فیصلہ کر دیں یا ان سے منہ موڑ دیں — اور اگر آپ منہ موڑ دیں تو وہ آپ کو کچھ نقصان نہیں پہنچا سکتے — اور اگر آپ فیصلہ کریں تو انصاف سے فیصلہ کریں — بے شک اللہ انصاف کرنے والوں سے محبت کرتا ہے",
"""۱۔ یہود کے جھوٹی بات سننے والے اور حرام کھانے والے — نبی ﷺ کے سامنے فیصلے کا اختیار۔
۲۔ ’’سَمَّاعُونَ لِلْكَذِبِ أَكَّالُونَ لِلسُّحْتِ‘‘ — وہ جھوٹی بات سننے والے ہیں — حرام (مال) کھانے والے ہیں — یعنی رشوت اور حرام آمدنی والے۔
۳۔ ’’فَإِن جَاءُوكَ فَاحْكُم بَيْنَهُمْ أَوْ أَعْرِضْ عَنْهُمْ‘‘ — پس اگر وہ آپ کے پاس آئیں تو آپ ان کے درمیان فیصلہ کر دیں یا ان سے منہ موڑ دیں — یعنی نبی ﷺ کو اختیار دیا گیا۔
۴۔ ’’وَإِن تُعْرِضْ عَنْهُمْ فَلَن يَضُرُّوكَ شَيْئًا‘‘ — اور اگر آپ منہ موڑ دیں تو وہ آپ کو کچھ نقصان نہیں پہنچا سکتے۔
۵۔ ’’وَإِنْ حَكَمْتَ فَاحْكُم بَيْنَهُم بِالْقِسْطِ إِنَّ اللّٰہَ يُحِبُّ الْمُقْسِطِينَ‘‘ — اور اگر آپ فیصلہ کریں تو انصاف سے فیصلہ کریں — بے شک اللہ انصاف کرنے والوں سے محبت کرتا ہے — یعنی فیصلہ انصاف سے ہو۔
۶۔ عملی سبق: فیصلے میں انصاف کرو؛ اللہ کی محبت حاصل کرو۔"""
),
712: (
"اور وہ آپ سے فیصلہ کیوں کرواتے ہیں — حالانکہ ان کے پاس تورات موجود ہے — جس میں اللہ کا فیصلہ ہے — پھر اس کے بعد وہ منہ موڑ لیتے ہیں — اور وہ ایمان والے نہیں ہیں",
"""۱۔ یہود کے پاس تورات ہو — پھر بھی نبی ﷺ سے فتویٰ مانگتے ہیں مگر عمل نہیں کرتے۔
۲۔ ’’وَكَيْفَ يُحَكِّمُونَكَ وَعِندَهُمُ التَّوْرَاةُ فِيهَا حُكْمُ اللّٰہِ‘‘ — اور وہ آپ سے فیصلہ کیوں کرواتے ہیں — حالانکہ ان کے پاس تورات موجود ہے — جس میں اللہ کا فیصلہ ہے — یعنی یہ منافقانہ رویہ ہے۔
۳۔ ’’ثُمَّ يَتَوَلَّوْنَ مِن بَعْدِ ذَٰلِكَ وَمَا أُولَٰئِكَ بِالْمُؤْمِنِينَ‘‘ — پھر اس کے بعد وہ منہ موڑ لیتے ہیں — اور وہ ایمان والے نہیں ہیں — یعنی فیصلہ مان کر پھر اس پر عمل نہیں کرتے۔
۴۔ عملی سبق: اللہ کے فیصلے کے سامنے ڈٹے رہو؛ صرف زبانی قبول نہ ہو۔"""
),
713: (
"بے شک ہم نے تورات اتاری — جس میں ہدایت اور نور ہے — اس کے مطابق وہ نبی جو (اللہ کے لیے) سر تسلیم خم کیے ہوئے تھے — یہود کے اہلِ علم اور (اللہ کے) فرمانبردار (لوگ) فیصلہ کرتے تھے — اس لیے کہ ان سے (اللہ کی) کتاب کی حفاظت کا عہد لیا گیا تھا — اور وہ اس پر گواہ تھے — پس تم لوگوں سے مت ڈرو — اور مجھ سے ڈرو — اور میری آیات کے بدلے تھوڑی سی قیمت (رشوت) مت لو — اور جو کوئی اس کے مطابق فیصلہ نہ کرے — جو اللہ نے نازل فرمایا — وہی کافر ہیں",
"""۱۔ تورات — ہدایت اور نور۔
۲۔ ’’إِنَّا أَنزَلْنَا التَّوْرَاةَ فِيهَا هُدًى وَنُورٌ‘‘ — بے شک ہم نے تورات اتاری — جس میں ہدایت اور نور ہے — یعنی تورات اللہ کی طرف سے نازل کردہ کتاب تھی۔
۳۔ ’’يَحْكُمُ بِهَا النَّبِيُّونَ الَّذِينَ أَسْلَمُوا لِلَّذِينَ هَادُوا وَالرَّبَّانِيُّونَ وَالْأَحْبَارُ‘‘ — اس کے مطابق وہ نبی جو (اللہ کے لیے) سر تسلیم خم کیے ہوئے تھے — یہود کے اہلِ علم اور (اللہ کے) فرمانبردار (لوگ) فیصلہ کرتے تھے۔
۴۔ ’’بِمَا اسْتُحْفِظُوا مِن كِتَابِ اللّٰہِ وَكَانُوا عَلَيْهِ شُهَدَاءَ‘‘ — اس لیے کہ ان سے (اللہ کی) کتاب کی حفاظت کا عہد لیا گیا تھا — اور وہ اس پر گواہ تھے — یعنی انہوں نے کتاب کی حفاظت کا عہد لیا تھا۔
۵۔ ’’فَلَا تَخْشَوُا النَّاسَ وَاخْشَوْنِ وَلَا تَشْتَرُوا بِآيَاتِي ثَمَنًا قَلِيلًا‘‘ — پس تم لوگوں سے مت ڈرو — اور مجھ سے ڈرو — اور میری آیات کے بدلے تھوڑی سی قیمت (رشوت) مت لو — یعنی رشوت اور دنیا کے لالچ میں فیصلے بدلنا حرام ہے۔
۶۔ ’’وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللّٰہُ فَأُولَٰئِكَ هُمُ الْكَافِرُونَ‘‘ — اور جو کوئی اس کے مطابق فیصلہ نہ کرے — جو اللہ نے نازل فرمایا — وہی کافر ہیں — یعنی اللہ کے فیصلے کے خلاف فیصلہ کرنا کفر ہے۔
۷۔ عملی سبق: دنیا کے لالچ میں انصاف چھوڑو مت؛ اللہ سے ڈرو۔"""
),
714: (
"اور ہم نے ان پر اس میں یہ لازم کر دیا کہ: جان کا بدلہ جان — آنکھ کا بدلہ آنکھ — ناک کا بدلہ ناک — کان کا بدلہ کان — دانت کا بدلہ دانت — اور زخموں کا بدلہ بھی بدلہ ہے — پھر جو کوئی اس (قصاص) کو معاف کر دے تو یہ اس کے لیے (گناہ کی) کفارت ہوگا — اور جو کوئی اس کے مطابق فیصلہ نہ کرے — جو اللہ نے نازل فرمایا — وہی ظالم ہیں",
"""۱۔ تورات کے قصاص کے احکام — برابری کی بنیاد پر۔
۲۔ ’’وَكَتَبْنَا عَلَيْهِمْ فِيهَا أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالْأَنفَ بِالْأَنفِ وَالْأُذُنَ بِالْأُذُنِ وَالسِّنَّ بِالسِّنِّ وَالْجُرُوحَ قِصَاصٌ‘‘ — اور ہم نے ان پر اس میں یہ لازم کر دیا کہ: جان کا بدلہ جان — آنکھ کا بدلہ آنکھ — ناک کا بدلہ ناک — کان کا بدلہ کان — دانت کا بدلہ دانت — اور زخموں کا بدلہ بھی بدلہ ہے — یعنی قصاص برابری کے اصول پر ہے۔
۳۔ ’’فَمَن تَصَدَّقَ بِهِ فَهُوَ كَفَّارَۃٌ لَّهُ‘‘ — پھر جو کوئی اس (قصاص) کو معاف کر دے تو یہ اس کے لیے (گناہ کی) کفارت ہوگا — یعنی معاف کرنا ثواب ہے۔
۴۔ ’’وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللّٰہُ فَأُولَٰئِكَ هُمُ الظَّالِمُونَ‘‘ — اور جو کوئی اس کے مطابق فیصلہ نہ کرے — جو اللہ نے نازل فرمایا — وہی ظالم ہیں۔
۵۔ عملی سبق: انصاف کے ساتھ بدلہ لو — معاف کرنا بھی اسی کا حصہ ہے۔"""
),
715: (
"اور ہم نے ان (نبیوں) کے پیچھے عیسیٰ ابنِ مریمؑ کو — ان کے پیچھے — بھیجا — ان کے سامنے تورات کی — جو ان کے پاس ہے — تصدیق کرتے ہوئے — اور ہم نے انہیں انجیل دی — جس میں ہدایت اور نور ہے — اور ان کے سامنے تورات کی — جو ان کے پاس ہے — تصدیق کرتے ہوئے — اور یہ پرہیزگاروں کے لیے ہدایت اور نصیحت ہے",
"""۱۔ عیسیٰؑ — تورات کے پیچھے انجیل لائے۔
۲۔ ’’وَقَفَّيْنَا عَلَىٰ آثَارِهِم بِعِيسَى ابْنِ مَرْيَمَ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرَاةِ‘‘ — اور ہم نے ان (نبیوں) کے پیچھے عیسیٰ ابنِ مریمؑ کو — ان کے پیچھے — بھیجا — ان کے سامنے تورات کی — جو ان کے پاس ہے — تصدیق کرتے ہوئے۔
۳۔ ’’وَآتَيْنَاهُ الْإِنجِيلَ فِيهِ هُدًى وَنُورٌ وَمُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ التَّوْرَاةِ وَهُدًى وَمَوْعِظَۃً لِّلْمُتَّقِينَ‘‘ — اور ہم نے انہیں انجیل دی — جس میں ہدایت اور نور ہے — اور ان کے سامنے تورات کی — جو ان کے پاس ہے — تصدیق کرتے ہوئے — اور یہ پرہیزگاروں کے لیے ہدایت اور نصیحت ہے۔
۴۔ عملی سبق: عیسیٰؑ نبی تھے — انجیلیں اللہ کی طرف سے نازل ہوئی تھیں؛ توحید پر ڈٹے رہو۔"""
),
716: (
"اور اہلِ انجیل کو چاہیے کہ وہ اس کے مطابق فیصلہ کریں — جو اللہ نے اس میں نازل فرمایا — اور جو کوئی اس کے مطابق فیصلہ نہ کرے — جو اللہ نے نازل فرمایا — وہی نافرمان ہیں",
"""۱۔ اہلِ انجیل — انجیل کے مطابق فیصلہ کریں۔
۲۔ ’’وَلْيَحْكُمْ أَهْلُ الْإِنجِيلِ بِمَا أَنزَلَ اللّٰہُ فِيهِ‘‘ — اور اہلِ انجیل کو چاہیے کہ وہ اس کے مطابق فیصلہ کریں — جو اللہ نے اس میں نازل فرمایا — یعنی اللہ کا نازل کردہ قانون — بہترین قانون ہے۔
۳۔ ’’وَمَن لَّمْ يَحْكُم بِمَا أَنزَلَ اللّٰہُ فَأُولَٰئِكَ هُمُ الْفَاسِقُونَ‘‘ — اور جو کوئی اس کے مطابق فیصلہ نہ کرے — جو اللہ نے نازل فرمایا — وہی نافرمان ہیں — یعنی اللہ کے احکام کی خلاف ورزی فسق ہے۔
۴۔ عملی سبق: اللہ کے نازل کردہ احکام کی پابندی کرو۔"""
),
717: (
"اور ہم نے آپ کی طرف — حق کے ساتھ — کتاب نازل کی — ان سے پہلے (نازل ہوئی) کتاب کی — ان کے سامنے — تصدیق کرتے ہوئے اور اس پر نگران (محافظ) ہو کر — پس آپ ان کے درمیان — اس کے مطابق جو اللہ نے نازل فرمایا — فیصلہ کریں — اور آپ کے پاس جو حق آیا ہے — اس سے ان کے نفسانی خواہشات کی پیروی نہ کریں — ہم نے تم میں سے ہر ایک کے لیے طریقہ اور راہ مقرر کی ہے — اور اگر اللہ چاہتا تو تمہیں ایک امت بنا دیتا — لیکن (یہ) اس لیے کہ تمہیں — جو اس نے تمہیں دیا ہے — اس میں آزمانے کے لیے — پس تم بھلائیوں میں سبقت کرو — تمہاری واپسی سب کی اللہ کی طرف ہوگی — پس وہ تمہیں — جو تم اختلاف کرتے تھے — سب کچھ بتائے گا",
"""۱۔ قرآن — پہلی کتابوں کا مصدق اور محافظ۔
۲۔ ’’وَأَنزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ‘‘ — اور ہم نے آپ کی طرف — حق کے ساتھ — کتاب نازل کی — ان سے پہلے (نازل ہوئی) کتاب کی — ان کے سامنے — تصدیق کرتے ہوئے اور اس پر نگران (محافظ) ہو کر — یعنی قرآن سابقہ کتابوں کی تصدیق کرتا ہے اور ان کی حفاظت کرتا ہے۔
۳۔ ’’فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللّٰہُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ عَمَّا جَاءَكَ مِنَ الْحَقِّ‘‘ — پس آپ ان کے درمیان — اس کے مطابق جو اللہ نے نازل فرمایا — فیصلہ کریں — اور آپ کے پاس جو حق آیا ہے — اس سے ان کے نفسانی خواہشات کی پیروی نہ کریں۔
۴۔ ’’لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَۃً وَمِنْهَاجًا‘‘ — ہم نے تم میں سے ہر ایک کے لیے طریقہ اور راہ مقرر کی ہے — یعنی شریعتیں مختلف ہو سکتی ہیں اللہ کی طرف سے۔
۵۔ ’’وَلَوْ شَاءَ اللّٰہُ لَجَعَلَكُمْ أُمَّۃً وَاحِدَۃً وَلَٰكِن لِّيَبْلُوَكُمْ فِي مَا آتَاكُمْ‘‘ — اور اگر اللہ چاہتا تو تمہیں ایک امت بنا دیتا — لیکن (یہ) اس لیے کہ تمہیں — جو اس نے تمہیں دیا ہے — اس میں آزمانے کے لیے — یعنی اختلاف آزمائش کا ذریعہ ہے۔
۶۔ ’’فَاسْتَبِقُوا الْخَيْرَاتِ إِلَى اللّٰہِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ‘‘ — پس تم بھلائیوں میں سبقت کرو — تمہاری واپسی سب کی اللہ کی طرف ہوگی — پس وہ تمہیں — جو تم اختلاف کرتے تھے — سب کچھ بتائے گا — یعنی بھلائی میں سبقت کرو۔
۷۔ عملی سبق: حق کے فیصلے پر ڈٹے رہو؛ بھلائیوں میں سبقت کرو۔"""
),
718: (
"اور چاہیے کہ آپ ان کے درمیان اس کے مطابق فیصلہ کریں — جو اللہ نے نازل فرمایا — اور ان کے نفسانی خواہشات کی پیروی نہ کریں — اور ان سے ہوشیار رہیں — (کہ) وہ آپ کو اس میں سے کچھ سے — جو اللہ نے آپ پر نازل فرمایا — فتنوں میں نہ ڈالیں — پس اگر وہ منہ موڑ لیں تو جان لو کہ اللہ ان کے بعض گناہوں کے سبب انہیں سزا دینا چاہتا ہے — اور بے شک اکثر لوگ نافرمان ہیں",
"""۱۔ نبی ﷺ کو — فتویٰ ہونے کے بعد بھی — ہوشیار رہنے کا حکم۔
۲۔ ’’وَأَنِ احْكُم بَيْنَهُم بِمَا أَنزَلَ اللّٰہُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ‘‘ — اور چاہیے کہ آپ ان کے درمیان اس کے مطابق فیصلہ کریں — جو اللہ نے نازل فرمایا — اور ان کے نفسانی خواہشات کی پیروی نہ کریں۔
۳۔ ’’وَاحْذَرْهُمْ أَن يَفْتِنُوكَ عَن بَعْضِ مَا أَنزَلَ اللّٰہُ إِلَيْكَ‘‘ — اور ان سے ہوشیار رہیں — (کہ) وہ آپ کو اس میں سے کچھ سے — جو اللہ نے آپ پر نازل فرمایا — فتنوں میں نہ ڈالیں — یعنی دشمن آپ کو سمجھوتے پر مجبور کرنے کی کوشش کریں گے۔
۴۔ ’’فَإِن تَوَلَّوْا فَاعْلَمْ أَنَّمَا يُرِيدُ اللّٰہُ أَن يُصِيبَهُم بِبَعْضِ ذُنُوبِهِمْ‘‘ — پس اگر وہ منہ موڑ لیں تو جان لو کہ اللہ ان کے بعض گناہوں کے سبب انہیں سزا دینا چاہتا ہے — یعنی ان کا انکار ان کے گناہوں کی سزا ہے۔
۵۔ ’’وَإِنَّ كَثِيرًا مِّنَ النَّاسِ لَفَاسِقُونَ‘‘ — اور بے شک اکثر لوگ نافرمان ہیں۔
۶۔ عملی سبق: حق میں سمجھوتہ نہ کرو؛ اللہ کے حکم پر ڈٹے رہو۔"""
),
719: (
"کیا وہ پھر بھی جاہلیت کے فیصلے چاہتے ہیں — اور یقین رکھنے والی قوم کے لیے — کس کا فیصلہ بہتر ہے — اللہ سے بہتر تو کوئی نہیں",
"""۱۔ جاہلیت کا فیصلہ — اور اللہ کا فیصلہ۔
۲۔ ’’أَفَحُكْمَ الْجَاهِلِيَّۃِ يَبْغُونَ‘‘ — کیا وہ پھر بھی جاہلیت کے فیصلے چاہتے ہیں — یعنی ظالمانہ فیصلے چاہتے ہیں۔
۳۔ ’’وَمَنْ أَحْسَنُ مِنَ اللّٰہِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ‘‘ — اور یقین رکھنے والی قوم کے لیے — کس کا فیصلہ بہتر ہے — اللہ سے بہتر تو کوئی نہیں — یعنی اللہ کا فیصلہ سب سے بہتر ہے۔
۴۔ عملی سبق: اللہ کے فیصلے کو سب سے بہتر سمجھو؛ جاہلیت کے فیصلے سے بچو۔"""
),
}
